from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from kubernetes_asyncio import client

router = APIRouter(prefix="/k8s/namespaces")

class ScalePayload(BaseModel):
    replicas: int

@router.post("/{namespace}/deployments/{deployment_name}/scale")
async def scale_namespaced_deployment(
    namespace: str,
    deployment_name: str,
    payload: ScalePayload,
    current_user: User = Depends(get_current_user),
    apps_api: client.AppsV1Api = Depends(get_k8s_apps_api)
):
    if namespace not in current_user.allowed_namespaces:
        raise HTTPException(status_code=403, detail="Forbidden: You cannot modify resources in this namespace")

    scale_spec = {"spec": {"replicas": max(0, min(payload.replicas, 20))}}
    try:
        updated_scale = await apps_api.patch_namespaced_deployment_scale(
            name=deployment_name,
            namespace=namespace,
            body=scale_spec
        )
    except client.exceptions.ApiException as e:
        raise HTTPException(status_code=e.status, detail=e.reason)

    return {
        "namespace": namespace,
        "deployment": deployment_name,
        "desired_replicas": updated_scale.spec.replicas
    }
